import {
  response2
} from "./fetch-acgs9zzk.js";
import {
  Api2
} from "./fetch-jxc39wgw.js";

// src/handlers/model.ts
import { Model } from "@opencode/core/model";
import { Effect } from "effect";
import { HttpApiBuilder } from "effect/unstable/httpapi";
var ModelHandler2 = HttpApiBuilder.group(Api2, "server.model", (handlers) => Effect.gen(function* () {
  return handlers.handle("model.list", Effect.fn(function* () {
    const models = yield* Model.Service;
    return yield* response2(models.available());
  })).handle("model.default", Effect.fn(function* () {
    const models = yield* Model.Service;
    return yield* response2(models.default());
  }));
}));

export { ModelHandler2 };
